cat > __bench__/tmp_perf_probe.test.ts << 'EOF'
import { describe, expect, it } from 'vitest';
import { compile } from '../src/index';

describe('probe', () => {
  it('generic path perf for digit-like pattern', () => {
    const stream = compile('(?:\\d)+').stream();
    const chunk = '7'.repeat(1024);
    const started = performance.now();
    for (let count = 0; count < 200; count += 1) stream.feed(chunk);
    stream.end();
    console.log('elapsed for 200 chunks (200KB):', performance.now() - started);
  });
});
EOF
node_modules/.bin/vitest run __bench__/tmp_perf_probe.test.ts --config vitest.config.ts 2>&1 | tail -40
